function useFocusTrap(ref: React.RefObject<HTMLElement | null>) {
  useEffect(() => {
    const root: HTMLElement = ref.current as HTMLElement
    if (!root) return
    const selector = 'button:not([disabled]), input:not([disabled]), select:not([disabled]), textarea:not([disabled]), [tabindex]:not([tabindex="-1"])'
    const focusables = (): HTMLElement[] => Array.from(root.querySelectorAll<HTMLElement>(selector))
    focusables()[0]?.focus()
    const onKeyDown = (event: KeyboardEvent) => {
      if (event.key !== 'Tab') return
      const items = focusables(); if (!items.length) return
      const first = items[0]; const last = items[items.length - 1]
      if (event.shiftKey && document.activeElement === first) { event.preventDefault(); last.focus() }
      else if (!event.shiftKey && document.activeElement === last) { event.preventDefault(); first.focus() }
    }
    root.addEventListener('keydown', onKeyDown); return () => root.removeEventListener('keydown', onKeyDown)
  }, [ref])
}

function ScanModal({ repos, scanners, onClose, onSubmit, onAddScanner }) {
  const enabledScanners = scanners.filter(s => s.enabled)
  const [repo, setRepo] = useState(repos[0]?.id || '')
  const [scanner, setScanner] = useState(enabledScanners[0]?.id || '')
  const [mode, setMode] = useState('incremental')
  const [confirmFull, setConfirmFull] = useState(false)
  const modalRef = useRef<HTMLDivElement>(null); useFocusTrap(modalRef)
  const submit = () => mode === 'full' ? setConfirmFull(true) : onSubmit({ repositoryId: repo, scanner, mode })
  return <div className="modal-backdrop" onClick={onClose}><div ref={modalRef} className="modal" role="dialog" aria-modal="true" aria-labelledby="scan-title" onClick={e => e.stopPropagation()}><div className="modal-head"><div><h2 id="scan-title">Run a security scan</h2><p>Start an isolated execution against a prepared repository workspace.</p></div><button aria-label="Close scan dialog" onClick={onClose}><Icon name="close" size={20}/></button></div>{!repos.length ? <div className="empty-state"><span>Add a repository before starting a scan.</span></div> : <><label>Repository<Select ariaLabel="Repository" value={repo} onChange={e => setRepo(e.target.value)} options={repos.map(r => ({ value: r.id, label: r.name }))}/></label>{!enabledScanners.length ? <div className="empty-state"><span>Enable a scanner before starting a scan.</span><button className="text-button" onClick={onAddScanner}>Add scanner <Icon name="arrow" size={13}/></button></div> : <><label>Scanner<Select ariaLabel="Scanner" value={scanner} onChange={e => setScanner(e.target.value)} options={enabledScanners.map(s => ({ value: s.id, label: s.name }))}/></label><label>Scan mode<Select ariaLabel="Scan mode" value={mode} onChange={e => setMode(e.target.value)} options={[{ value: 'incremental', label: 'Incremental' }, { value: 'full', label: 'Full' }]}/></label><div className="modal-actions"><button className="secondary" onClick={onClose}>Cancel</button><button className="primary" onClick={submit}>Queue scan <Icon name="arrow" size={14}/></button></div></>}</>}</div>{confirmFull && <div className="modal-backdrop confirm-layer" onClick={() => setConfirmFull(false)}><div className="modal confirm-modal" role="alertdialog" aria-modal="true" aria-labelledby="full-scan-title" onClick={e => e.stopPropagation()}><div className="modal-head"><div><h2 id="full-scan-title">Confirm full scan</h2><p>A full scan may take longer and inspect the complete repository history.</p></div><button aria-label="Close confirmation" onClick={() => setConfirmFull(false)}><Icon name="close" size={20}/></button></div><div className="modal-actions"><button className="secondary" onClick={() => setConfirmFull(false)}>Cancel</button><button className="primary" onClick={() => onSubmit({ repositoryId: repo, scanner, mode })}>Continue <Icon name="arrow" size={14}/></button></div></div></div>}</div>
}

