  const filteredRepos = useMemo(() => repos.filter(r => r.name.toLowerCase().includes(query.toLowerCase())), [repos, query]); const navigate = view => { setActive(view); const next = new URL(window.location.href); next.searchParams.set('view', view); window.history.pushState({ view }, '', next) }
  const activeRepo = repos.find(r => r.id === active)
  useEffect(() => { const handleHistory = () => setActive(new URLSearchParams(window.location.search).get('view') || 'Dashboard'); window.addEventListener('popstate', handleHistory); return () => window.removeEventListener('popstate', handleHistory) }, [])
  useEffect(() => { if (!apiEnabled || !authReady) return undefined; const loaders = { Dashboard: [loadRepositories, loadRuns, loadFindings], Repositories: [loadRepositories], Scans: [loadRuns], Renovate: [loadRuns], TruffleHog: [loadRuns], Findings: [loadFindings], Alerts: [loadRuns, loadFindings], Settings: [loadSettings, loadScanners], Policies: [loadSettings], 'Audit Logs': [loadAudit], System: [loadRepositories, loadRuns] }[active] || []; const update = async () => { const values = await Promise.all(loaders.map(loader => loader(fetch, token))); loaders.forEach((loader, i) => { if (loader === loadRepositories) setRepos(values[i]); if (loader === loadRuns) setRuns(values[i]); if (loader === loadFindings) setFindings(values[i]); if (loader === loadSettings) setSettings(values[i]); if (loader === loadScanners) setScanners(values[i]); if (loader === loadAudit) setAudit(values[i]) }); setLastChecked(new Date()) }; update(); const timer = setInterval(update, 5000); return () => clearInterval(timer) }, [apiEnabled, authReady, role, token, active])
